import { createRequire } from "node:module";
const require = createRequire(import.meta.url);
const { road } = require("outside-package");
const root = process.platform === "win32" ? "B:\\~BUN\\root\\" : "/$bunfs/root/";
export const look = () => [
  road("import.meta.require.cache of an ES module outside", () => import.meta.require.cache),
  road("import.meta.require.main", () => import.meta.require.main),
  road("import.meta.require of a file in the executable", () => import.meta.require(root + "inner.cjs")),
  road("createRequire(import.meta.url).cache", () => require.cache),
  road("import.meta.main and its relatives", () => [import.meta.main, import.meta.url, import.meta.dir]),
];
export const lookLater = async () => {
  let found;
  try { found = await import(root + "inner.cjs"); } catch (error) { return ["import() of a file in the executable: rejects " + error.name]; }
  return [road("import() of a file in the executable", () => found)];
};
